import { act, render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it } from 'vitest';
import { ErrorProvider, useError } from './ErrorContext';

function TestConsumer() {
  const { error, showError, clearError } = useError();
  return (
    <div>
      <span data-testid="error">{error}</span>
      <button onClick={() => showError('Something went wrong')}>
        Trigger error
      </button>
      <button onClick={clearError}>Clear error</button>
    </div>
  );
}

describe('ErrorContext', () => {
  it('starts with no error', () => {
    render(
      <ErrorProvider>
        <TestConsumer />
      </ErrorProvider>,
    );

    expect(screen.getByTestId('error')).toHaveTextContent('');
  });

  it('shows an error message', async () => {
    const user = userEvent.setup();

    render(
      <ErrorProvider>
        <TestConsumer />
      </ErrorProvider>,
    );

    await user.click(screen.getByRole('button', { name: 'Trigger error' }));

    expect(screen.getByTestId('error')).toHaveTextContent(
      'Something went wrong',
    );
  });

  it('clears the error', async () => {
    const user = userEvent.setup();

    render(
      <ErrorProvider>
        <TestConsumer />
      </ErrorProvider>,
    );

    await user.click(screen.getByRole('button', { name: 'Trigger error' }));
    expect(screen.getByTestId('error')).toHaveTextContent(
      'Something went wrong',
    );

    await user.click(screen.getByRole('button', { name: 'Clear error' }));
    expect(screen.getByTestId('error')).toHaveTextContent('');
  });

  it('throws when useError is used outside ErrorProvider', () => {
    // Suppress console.error for the expected throw
    const spy = vi.spyOn(console, 'error').mockImplementation(() => {});

    expect(() => render(<TestConsumer />)).toThrow(
      'useError must be used within an ErrorProvider',
    );

    spy.mockRestore();
  });
});

import {
  createContext,
  useCallback,
  useContext,
  useState,
  type ReactNode,
} from 'react';

interface ErrorContextValue {
  error: string | null;
  showError: (message: string) => void;
  clearError: () => void;
}

const ErrorContext = createContext<ErrorContextValue | null>(null);

export function useError(): ErrorContextValue {
  const ctx = useContext(ErrorContext);
  if (!ctx) {
    throw new Error('useError must be used within an ErrorProvider');
  }
  return ctx;
}

export function ErrorProvider({ children }: { children: ReactNode }) {
  const [error, setError] = useState<string | null>(null);

  const showError = useCallback((message: string) => {
    setError(message);
  }, []);

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  return (
    <ErrorContext.Provider value={{ error, showError, clearError }}>
      {children}
    </ErrorContext.Provider>
  );
}

