import { render, screen, fireEvent } from '@testing-library/react';
import { describe, expect, it, vi } from 'vitest';
import ErrorSnackbar from './ErrorSnackbar';
import { ErrorProvider } from './ErrorContext';
import { useError } from './ErrorContext';

const { mockShowError } = vi.hoisted(() => ({
  mockShowError: vi.fn(),
}));

vi.mock('./ErrorContext', async () => {
  const actual = await vi.importActual('./ErrorContext');
  return {
    ...actual,
    useError: () => ({
      error: 'Token refresh failed — please log in again.',
      showError: mockShowError,
      clearError: vi.fn(),
    }),
  };
});

describe('ErrorSnackbar', () => {
  it('renders the error message in a MUI Alert', () => {
    render(<ErrorSnackbar />);

    expect(
      screen.getByText('Token refresh failed — please log in again.'),
    ).toBeInTheDocument();
  });

  it('renders a close button that calls clearError', () => {
    render(<ErrorSnackbar />);

    const closeButton = screen.getByRole('button', { name: 'Close' });
    expect(closeButton).toBeInTheDocument();
  });

  it('renders nothing when there is no error', () => {
    // Override the mock for this test
    vi.mocked(useError).mockReturnValue({
      error: null,
      showError: mockShowError,
      clearError: vi.fn(),
    });

    const { container } = render(<ErrorSnackbar />);

    expect(container.firstChild).toBeNull();
  });
});

// Separate describe for the integrated render to test clearError callback
describe('ErrorSnackbar integration', () => {
  it('calls clearError when the close button is clicked', () => {
    const clearError = vi.fn();

    vi.mocked(useError).mockReturnValue({
      error: 'Test error',
      showError: vi.fn(),
      clearError,
    });

    render(<ErrorSnackbar />);

    fireEvent.click(screen.getByRole('button', { name: 'Close' }));

    expect(clearError).toHaveBeenCalledTimes(1);
  });
});

import { Alert, Snackbar } from '@mui/material';
import { useError } from './ErrorContext';

export default function ErrorSnackbar() {
  const { error, clearError } = useError();

  if (!error) {
    return null;
  }

  return (
    <Snackbar
      open
      autoHideDuration={8000}
      onClose={clearError}
      anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
    >
      <Alert
        severity="error"
        variant="filled"
        onClose={clearError}
        sx={{ width: '100%' }}
      >
        {error}
      </Alert>
    </Snackbar>
  );
}

import { fireEvent, render, screen } from '@testing-library/react';
